1	"use strict";
2	
3	/* =====================================================================
4	 * StructEd · 结构文档工作台
5	 * ---------------------------------------------------------------------
6	 * 设计核心：全文只有一份数据模型 doc = { title, blocks[] }。
7	 * 大纲、编辑器、预览三个视图全部由这份数据派生，任何编辑先改模型，
8	 * 再同步重绘三个视图 —— 因此“结构化编辑与预览一致”由构造保证。
9	 *
10	 * “编辑不破坏结构”由规则守卫（attempt）保证：
11	 *   R1 唯一 H1  —— 文档标题是独立字段，恒为全文唯一一级标题，不提供
12	 *                  任何能改变其级别的操作。
13	 *   R2 层级连续 —— 内容标题只有 H2/H3 两级；任何结构性操作（改类型、
14	 *                  移动、复制、插入、删除）先在副本上试运行并校验，
15	 *                  不满足 “标题级别 ≤ 前一个标题级别 + 1” 则整体拒绝。
16	 *   R3 标题非空 —— 空标题允许键入过程瞬时存在，但实时标记，
17	 *                  并在结构体检面板中列出。
18	 * =================================================================== */
19	
20	/* ---------------- 常量与工具 ---------------- */
21	
22	const STORAGE_KEY = "structed:doc:v1";
23	
24	const TYPES = {
25	  h2:      { label: "章节 H2", group: "heading", level: 2 },
26	  h3:      { label: "小节 H3", group: "heading", level: 3 },
27	  p:       { label: "段落",     group: "text" },
28	  bullet:  { label: "列表项",   group: "list" },
29	  num:     { label: "编号项",   group: "list" },
30	  quote:   { label: "引用",     group: "text" },
31	  callout: { label: "提示框",   group: "callout" },
32	};
33	
34	const PLACEHOLDER = {
35	  h2: "章节标题（如：背景与目标）",
36	  h3: "小节标题（如：场景一）",
37	  p: "输入正文，按 Enter 快速新建段落",
38	  bullet: "列表项内容",
39	  num: "编号项内容",
40	  quote: "引用的文字",
41	  callout: "要强调的提示内容",
42	};
43	
44	const uid = () => "b" + Math.random().toString(36).slice(2, 9) + Date.now().toString(36).slice(-3);
45	const clone = (o) => JSON.parse(JSON.stringify(o));
46	const isHeading = (b) => TYPES[b.type].group === "heading";
47	
48	/* ---------------- 示例文档（首屏内联数据） ---------------- */
49	
50	function makeSampleDoc() {
51	  const mk = (type, text) => ({ id: uid(), type, text });
52	  return {
53	    title: "「星云」协作白板 · 产品需求文档 v0.3",
54	    blocks: [
55	      mk("h2", "背景与目标"),
56	      mk("p", "远程团队在头脑风暴与评审环节缺少一块“可以一起动手”的画布。星云协作白板以低延迟同步为核心，让分布各地的成员在同一块板子上写字、贴便签、连线。"),
57	      mk("bullet", "目标：单板并发编辑 ≥ 50 人，操作同步延迟 P95 ≤ 120ms"),
58	      mk("bullet", "范围：白板编辑、便签、基础图形、模板市场（一期不含评论与历史版本）"),
59	      mk("bullet", "非目标：视频会议、第三方存储直传"),
60	      mk("h2", "核心场景"),
61	      mk("h3", "场景一：跨城市头脑风暴"),
62	      mk("p", "主持人从模板库新建“鱼骨图”板，成员扫码进入后各自贴便签；板面按区域自动聚合同一主题的便签。"),
63	      mk("h3", "场景二：迭代评审复盘"),
64	      mk("p", "评审结束后，将白板一键归档到项目空间，并生成只读快照链接供缺席者回看。"),
65	      mk("callout", "一期白板不承担审批流，评审结论请回填至需求单。"),
66	      mk("h2", "里程碑"),
67	      mk("num", "M1（第 4 周）：白板内核 + 便签，支持 10 人并发"),
68	      mk("num", "M2（第 8 周）：图形与模板市场，支持 30 人并发"),
69	      mk("num", "M3（第 12 周）：归档快照与权限加固，全量发布"),
70	      mk("h3", "待确认事项"),
71	      mk("p", "模板市场是否需要审核流，法务侧尚未给出结论，见风险登记册 R-07。"),
72	      mk("quote", "先做一秒钟内能看到对方光标移动的白板，再谈其它。"),
73	    ],
74	  };
75	}
76	
77	/* ---------------- 状态 ---------------- */
78	
79	let doc;                       // 唯一数据模型
80	let undoStack = [];
81	let redoStack = [];
82	let activeId = null;           // 当前聚焦块
83	let typingArmed = false;       // 连续键入期间只压一次撤销快照
84	let typingTimer = null;
85	let suppressToast = false;     // 自检时静默
86	let toastTimer = null;
87	let lastMsg = "就绪";
88	
89	/* ---------------- 持久化（可选增强，失败静默） ---------------- */
90	
91	function loadDoc() {
92	  try {
93	    const raw = localStorage.getItem(STORAGE_KEY);
94	    if (!raw) return null;
95	    const d = JSON.parse(raw);
96	    if (d && typeof d.title === "string" && Array.isArray(d.blocks)
97	        && d.blocks.every((b) => b && typeof b.id === "string" && typeof b.text === "string" && TYPES[b.type])) return d;
98	  } catch (e) { /* file:// 或隐私模式下可能不可用 */ }
99	  return null;
100	}
101	
102	function saveDoc() {
103	  try { localStorage.setItem(STORAGE_KEY, JSON.stringify(doc)); } catch (e) { /* 忽略 */ }
104	}
105	
106	/* ---------------- 结构校验（编辑器 / 预览 / 体检共用） ---------------- */
107	
108	function validate(d) {
109	  const issues = [];
110	  if (!d.title.trim()) {
111	    issues.push({ rule: "empty-title", blocking: false, msg: "文档标题为空（标题是全文唯一的 H1）" });
112	  }
113	  let prev = 1; // 文档标题恒为 1 级
114	  d.blocks.forEach((b, i) => {
115	    if (!isHeading(b)) return;
116	    const lvl = TYPES[b.type].level;
117	    if (lvl > prev + 1) {
118	      issues.push({
119	        rule: "level-jump", blocking: true, blockId: b.id,
120	        msg: `第 ${i + 1} 块：${TYPES[b.type].label} 出现在 H${prev} 之后，层级跳跃（H${prev} → H${lvl}）`,
121	      });
122	    }
123	    if (!b.text.trim()) {
124	      issues.push({ rule: "empty-heading", blocking: false, blockId: b.id, msg: `第 ${i + 1} 块：标题文字为空` });
125	    }
126	    prev = lvl;
127	  });
128	  return issues;
129	}
130	
131	/* 标题自动编号：h2 计 1、1、2…；h3 计 1.1、1.2…（仅派生展示用） */
132	function headingNumbers(d) {
133	  const map = new Map();
134	  let s = 0, t = 0;
135	  d.blocks.forEach((b) => {
136	    if (b.type === "h2") { s++; t = 0; map.set(b.id, String(s)); }
137	    else if (b.type === "h3") { t++; map.set(b.id, s + "." + t); }
138	  });
139	  return map;
140	}
141	
142	/* ---------------- 守卫式修改入口 ---------------- */
143	
144	/* 所有结构性操作先在副本上试运行：op 返回 {ok:false, reason} 可提前否决，
145	 * 否则跑结构校验，出现阻断级问题（层级跳跃）则整体拒绝并说明原因。 */
146	function attempt(op, { describe } = {}) {
147	  const trial = clone(doc);
148	  const verdict = op(trial);
149	  if (verdict && verdict.ok === false) {
150	    toast(verdict.reason, "warn");
151	    renderAll();
152	    return false;
153	  }
154	  const blocking = validate(trial).filter((i) => i.blocking);
155	  if (blocking.length) {
156	    toast("已阻止，" + blocking[0].msg, "warn");
157	    renderAll();
158	    return false;
159	  }
160	  pushUndo();
161	  typingArmed = false;
162	  clearTimeout(typingTimer);
163	  doc = trial;
164	  afterChange(describe || "已更新");
165	  return true;
166	}
167	
168	function setType(id, type) {
169	  return attempt((trial) => {
170	    const b = trial.blocks.find((x) => x.id === id);
171	    if (!b) return { ok: false, reason: "块不存在" };
172	    b.type = type;
173	  }, { describe: `已转换为「${TYPES[type].label}」` });
174	}
175	
176	function moveBlock(id, dir) {
177	  return attempt((trial) => {
178	    const i = trial.blocks.findIndex((x) => x.id === id);
179	    const j = i + dir;
180	    if (i < 0 || j < 0 || j >= trial.blocks.length) return { ok: false, reason: "已到文档边界" };
181	    [trial.blocks[i], trial.blocks[j]] = [trial.blocks[j], trial.blocks[i]];
182	  }, { describe: dir < 0 ? "已上移一块" : "已下移一块" });
183	}
184	
185	function duplicateBlock(id) {
186	  return attempt((trial) => {
187	    const i = trial.blocks.findIndex((x) => x.id === id);
188	    if (i < 0) return { ok: false, reason: "块不存在" };
189	    trial.blocks.splice(i + 1, 0, { ...clone(trial.blocks[i]), id: uid() });
190	  }, { describe: "已复制一块" });
191	}
192	
193	function insertAfter(id, type = "p") {
194	  let newId = null;
195	  const ok = attempt((trial) => {
196	    const i = id == null ? trial.blocks.length - 1 : trial.blocks.findIndex((x) => x.id === id);
197	    if (id != null && i < 0) return { ok: false, reason: "插入位置不存在" };
198	    const nb = { id: uid(), type, text: "" };
199	    trial.blocks.splice(i + 1, 0, nb);
200	    newId = nb.id;
201	  }, { describe: "已插入段落" });
202	  return ok ? newId : null;
203	}
204	
205	function removeBlock(id) {
206	  return attempt((trial) => {
207	    const i = trial.blocks.findIndex((x) => x.id === id);
208	    if (i < 0) return { ok: false, reason: "块不存在" };
209	    trial.blocks.splice(i, 1);
210	  }, { describe: "已删除一块" });
211	}
212	
213	/* ---------------- 撤销 / 重做 ---------------- */
214	
215	function pushUndo() {
216	  undoStack.push(clone(doc));
217	  if (undoStack.length > 100) undoStack.shift();
218	  redoStack.length = 0;
219	}
220	
221	function undo() {
222	  if (!undoStack.length) return;
223	  const focusId = activeId;
224	  redoStack.push(clone(doc));
225	  doc = undoStack.pop();
226	  typingArmed = false;
227	  clearTimeout(typingTimer);
228	  afterChange("已撤销");
229	  if (focusId) focusBlock(focusId);
230	}
231	
232	function redo() {
233	  if (!redoStack.length) return;
234	  const focusId = activeId;
235	  undoStack.push(clone(doc));
236	  doc = redoStack.pop();
237	  typingArmed = false;
238	  clearTimeout(typingTimer);
239	  afterChange("已重做");
240	  if (focusId) focusBlock(focusId);
241	}
242	
243	/* 键入类修改：连续输入只压一次“键入前”快照 */
244	function noteEditSnapshot() {
245	  if (typingArmed) {
246	    clearTimeout(typingTimer);
247	  } else {
248	    pushUndo();
249	    typingArmed = true;
250	  }
251	  typingTimer = setTimeout(() => { typingArmed = false; }, 900);
252	}
253	
254	function onBlockInput(id, value) {
255	  const b = doc.blocks.find((x) => x.id === id);
256	  if (!b || b.text === value) return;
257	  noteEditSnapshot();
258	  b.text = value;
259	  renderDerived();  // 文本编辑不动块结构，编辑器无需重绘（保住光标）
260	  saveDoc();
261	}
262	
263	function onTitleInput(value) {
264	  if (doc.title === value) return;
265	  noteEditSnapshot();
266	  doc.title = value;
267	  const el = document.querySelector(".doc-title-input");
268	  if (el) el.classList.toggle("is-empty", !value.trim());
269	  renderDerived();
270	  saveDoc();
271	}
272	
273	/* ---------------- 渲染：编辑器 ---------------- */
274	
275	function grow(el) {
276	  el.style.height = "auto";
277	  el.style.height = el.scrollHeight + "px";
278	}
279	
280	function placeCaretEnd(el) {
281	  el.focus();
282	  const n = el.value.length;
283	  try { el.setSelectionRange(n, n); } catch (e) { /* 非 受控元素时忽略 */ }
284	}
285	
286	function focusBlock(id) {
287	  const ta = document.querySelector(`#editor textarea.block-text[data-id="${id}"]`);
288	  if (!ta) return;
289	  placeCaretEnd(ta);
290	  ta.scrollIntoView({ block: "nearest" });
291	}
292	
293	function reveal(id) {
294	  activeId = id;
295	  renderEditor();
296	  focusBlock(id);
297	}
298	
299	function setActive(id) {
300	  if (activeId === id) { syncOutlineActive(); return; }
301	  activeId = id;
302	  document.querySelectorAll("#editor .block-row").forEach((r) => {
303	    r.classList.toggle("active", r.dataset.id === id);
304	  });
305	  syncOutlineActive();
306	}
307	
308	function toolBtn(label, title, onClick, disabled) {
309	  const btn = document.createElement("button");
310	  btn.type = "button";
311	  btn.className = "tool-btn";
312	  btn.textContent = label;
313	  btn.title = title;
314	  btn.setAttribute("aria-label", title);
315	  btn.disabled = !!disabled;
316	  btn.addEventListener("click", onClick);
317	  return btn;
318	}
319	
320	function makeTypeSelect(b) {
321	  const sel = document.createElement("select");
322	  sel.className = "type-select";
323	  sel.title = "转换块类型（受结构规则保护）";
324	  sel.setAttribute("aria-label", "块类型");
325	  Object.entries(TYPES).forEach(([t, meta]) => {
326	    const o = document.createElement("option");
327	    o.value = t;
328	    o.textContent = meta.label;
329	    sel.appendChild(o);
330	  });
331	  sel.value = b.type;
332	  sel.addEventListener("change", () => {
333	    const ok = setType(b.id, sel.value);
334	    if (!ok) sel.value = b.type; // 被守卫拒绝则回弹
335	  });
336	  return sel;
337	}
338	
339	function renderEditor() {
340	  const host = document.getElementById("editor");
341	  host.textContent = "";
342	
343	  // 唯一 H1：标题（独立字段，只可改文字，天然满足 R1）
344	  const title = document.createElement("textarea");
345	  title.className = "doc-title-input" + (doc.title.trim() ? "" : " is-empty");
346	  title.rows = 1;
347	  title.value = doc.title;
348	  title.placeholder = "输入文档标题…";
349	  title.setAttribute("aria-label", "文档标题（唯一的 H1）");
350	  title.addEventListener("input", () => { grow(title); onTitleInput(title.value); });
351	  title.addEventListener("focus", () => setActive("__title__"));
352	  title.addEventListener("keydown", (e) => {
353	    if (e.key === "Enter" && !e.isComposing) {
354	      e.preventDefault();
355	      const first = document.querySelector("#editor textarea.block-text");
356	      if (first) placeCaretEnd(first);
357	    }
358	  });
359	  host.appendChild(title);
360	
361	  doc.blocks.forEach((b, i) => {
362	    const row = document.createElement("div");
363	    row.className = "block-row t-" + b.type + (b.id === activeId ? " active" : "");
364	    row.dataset.id = b.id;
365	    if (isHeading(b) && !b.text.trim()) row.classList.add("is-empty-heading");
366	
367	    const gutter = document.createElement("div");
368	    gutter.className = "block-gutter";
369	    gutter.textContent = String(i + 1);
370	
371	    const main = document.createElement("div");
372	    main.className = "block-main";
373	    if (isHeading(b) && !b.text.trim()) {
374	      const flag = document.createElement("div");
375	      flag.className = "block-flag";
376	      flag.textContent = "⚠ 标题不能为空";
377	      main.appendChild(flag);
378	    }
379	
380	    const ta = document.createElement("textarea");
381	    ta.className = "block-text";
382	    ta.rows = 1;
383	    ta.value = b.text;
384	    ta.dataset.id = b.id;
385	    ta.placeholder = PLACEHOLDER[b.type];
386	    ta.setAttribute("aria-label", `${TYPES[b.type].label} · 第 ${i + 1} 块`);
387	    ta.addEventListener("input", () => { grow(ta); onBlockInput(b.id, ta.value); });
388	    ta.addEventListener("focus", () => setActive(b.id));
389	    ta.addEventListener("keydown", (e) => {
390	      if (e.key === "Enter" && !e.shiftKey && !e.isComposing) {
391	        e.preventDefault();
392	        const nid = insertAfter(b.id, "p");
393	        if (nid) reveal(nid);
394	      } else if (e.key === "Backspace" && ta.value === "") {
395	        e.preventDefault();
396	        const idx = doc.blocks.findIndex((x) => x.id === b.id);
397	        const prev = doc.blocks[idx - 1];
398	        if (prev) activeId = prev.id;
399	        if (removeBlock(b.id) && prev) { renderEditor(); focusBlock(prev.id); }
400	      }
401	    });
402	    main.appendChild(ta);
403	
404	    const tools = document.createElement("div");
405	    tools.className = "block-tools";
406	    tools.appendChild(makeTypeSelect(b));
407	    tools.appendChild(toolBtn("↑", "上移", () => moveBlock(b.id, -1), i === 0));
408	    tools.appendChild(toolBtn("↓", "下移", () => moveBlock(b.id, +1), i === doc.blocks.length - 1));
409	    tools.appendChild(toolBtn("⧉", "复制本块", () => duplicateBlock(b.id)));
410	    tools.appendChild(toolBtn("＋", "在下方插入段落", () => { const nid = insertAfter(b.id, "p"); if (nid) reveal(nid); }));
411	    tools.appendChild(toolBtn("✕", "删除本块", () => removeBlock(b.id)));
412	
413	    row.appendChild(gutter);
414	    row.appendChild(main);
415	    row.appendChild(tools);
416	    host.appendChild(row);
417	  });
418	
419	  const add = document.createElement("button");
420	  add.type = "button";
421	  add.className = "btn ghost add-block";
422	  add.textContent = "＋ 添加段落";
423	  add.addEventListener("click", () => { const nid = insertAfter(null, "p"); if (nid) reveal(nid); });
424	  host.appendChild(add);
425	
426	  host.querySelectorAll("textarea").forEach(grow);
427	}
428	
429	/* ---------------- 渲染：大纲 ---------------- */
430	
431	function outlineData(d) {
432	  const items = [{
433	    id: "__title__", lvl: 1, num: "H1",
434	    text: d.title.trim() || "（无标题）", isEmpty: !d.title.trim(),
435	  }];
436	  const nums = headingNumbers(d);
437	  d.blocks.forEach((b) => {
438	    if (b.type === "h2") items.push({ id: b.id, lvl: 2, num: nums.get(b.id), text: b.text, isEmpty: !b.text.trim() });
439	    if (b.type === "h3") items.push({ id: b.id, lvl: 3, num: nums.get(b.id), text: b.text, isEmpty: !b.text.trim() });
440	  });
441	  return items;
442	}
443	
444	function renderOutline() {
445	  const host = document.getElementById("outline");
446	  host.textContent = "";
447	  const items = outlineData(doc);
448	  items.forEach((it) => {
449	    const btn = document.createElement("button");
450	    btn.type = "button";
451	    btn.className = `outline-item lvl-${it.lvl === 1 ? "title" : it.lvl}` + (it.isEmpty ? " is-empty" : "")
452	      + (it.id === activeId ? " active" : "");
453	    btn.dataset.blockId = it.id;
454	    const chip = document.createElement("span");
455	    chip.className = "num-chip";
456	    chip.textContent = it.num;
457	    const label = document.createElement("span");
458	    label.textContent = it.text.length > 26 ? it.text.slice(0, 26) + "…" : it.text;
459	    btn.appendChild(chip);
460	    btn.appendChild(label);
461	    btn.title = it.text;
462	    btn.addEventListener("click", () => {
463	      if (it.id === "__title__") {
464	        placeCaretEnd(document.querySelector(".doc-title-input"));
465	      } else {
466	        const ta = document.querySelector(`#editor textarea.block-text[data-id="${it.id}"]`);
467	        if (ta) { placeCaretEnd(ta); ta.scrollIntoView({ block: "center" }); }
468	      }
469	    });
470	    host.appendChild(btn);
471	  });
472	  if (items.length === 1) {
473	    const tip = document.createElement("div");
474	    tip.className = "outline-empty";
475	    tip.textContent = "暂无标题块 —— 把某个块转换为「章节 H2」即可出现在大纲里。";
476	    host.appendChild(tip);
477	  }
478	  syncOutlineActive();
479	}
480	
481	function syncOutlineActive() {
482	  const items = document.querySelectorAll("#outline .outline-item");
483	  let hit = null;
484	  items.forEach((el) => {
485	    const on = el.dataset.blockId === activeId;
486	    el.classList.toggle("active", on);
487	    if (on) hit = el;
488	  });
489	  if (hit) hit.scrollIntoView({ block: "nearest" });
490	}
491	
492	/* ---------------- 渲染：预览（与编辑器同源的派生视图） ---------------- */
493	
494	function fillText(el, b) {
495	  const t = b.text.trim();
496	  if (t) {
497	    el.appendChild(document.createTextNode(t));
498	  } else {
499	    const empty = document.createElement("span");
500	    empty.className = "pv-empty";
501	    empty.textContent = TYPES[b.type].group === "heading" ? "（空标题）" : "（空）";
502	    el.appendChild(empty);
503	    el.appendChild(warnChip("空"));
504	  }
505	}
506	
507	function warnChip(text) {
508	  const chip = document.createElement("span");
509	  chip.className = "pv-warn-chip";
510	  chip.textContent = "⚠ " + text;
511	  return chip;
512	}
513	
514	function renderBlock(b, num) {
515	  let el;
516	  switch (b.type) {
517	    case "h2": case "h3": {
518	      el = document.createElement(b.type);
519	      const chip = document.createElement("span");
520	      chip.className = "num-chip";
521	      chip.textContent = num || "•";
522	      el.appendChild(chip);
523	      fillText(el, b);
524	      break;
525	    }
526	    case "p": {
527	      el = document.createElement("p");
528	      fillText(el, b);
529	      break;
530	    }
531	    case "quote": {
532	      el = document.createElement("blockquote");
533	      fillText(el, b);
534	      break;
535	    }
536	    case "callout": {
537	      el = document.createElement("div");
538	      el.className = "pv-callout";
539	      const icon = document.createElement("span");
540	      icon.className = "pv-callout-icon";
541	      icon.textContent = "ℹ";
542	      const body = document.createElement("div");
543	      body.className = "pv-callout-body";
544	      const strong = document.createElement("strong");
545	      strong.textContent = "提示 ";
546	      body.appendChild(strong);
547	      fillText(body, b);
548	      el.appendChild(icon);
549	      el.appendChild(body);
550	      break;
551	    }
552	    default: {
553	      el = document.createElement("p");
554	      fillText(el, b);
555	    }
556	  }
557	  el.dataset.node = "1";
558	  return el;
559	}
560	
561	function renderPreview() {
562	  const host = document.getElementById("preview");
563	  host.textContent = "";
564	  const nums = headingNumbers(doc);
565	
566	  const h1 = document.createElement("h1");
567	  h1.className = "pv-title";
568	  h1.dataset.node = "1";
569	  h1.appendChild(document.createTextNode(doc.title.trim() || "（无标题文档）"));
570	  if (!doc.title.trim()) h1.appendChild(warnChip("标题为空"));
571	  host.appendChild(h1);
572	
573	  const meta = document.createElement("div");
574	  meta.className = "pv-meta";
575	  meta.textContent = `StructEd 实时预览 · ${doc.blocks.length} 个内容块 · 同步于 ${new Date().toTimeString().slice(0, 8)}`;
576	  host.appendChild(meta);
577	
578	  if (doc.blocks.length === 0) {
579	    const p = document.createElement("p");
580	    p.className = "pv-empty";
581	    p.dataset.node = "1";
582	    p.textContent = "文档正文为空 —— 回到编辑器添加内容块。";
583	    host.appendChild(p);
584	    return;
585	  }
586	
587	  let i = 0;
588	  while (i < doc.blocks.length) {
589	    const b = doc.blocks[i];
590	    if (b.type === "bullet" || b.type === "num") {
591	      const list = document.createElement(b.type === "bullet" ? "ul" : "ol");
592	      while (i < doc.blocks.length && doc.blocks[i].type === b.type) {
593	        const li = document.createElement("li");
594	        li.dataset.node = "1";
595	        fillText(li, doc.blocks[i]);
596	        list.appendChild(li);
597	        i++;
598	      }
599	      list.dataset.node = "0"; // 列表容器本身不计节点，计数落在每个 li
600	      host.appendChild(list);
601	      continue;
602	    }
603	    host.appendChild(renderBlock(b, nums.get(b.id) || ""));
604	    i++;
605	  }
606	}
607	
608	/* 一致性自检：模型节点数（正文块 + 唯一 H1）与预览 DOM 节点数必须相等 */
609	function auditConsistency() {
610	  const previewNodes = document.querySelectorAll("#preview [data-node='1']").length;
611	  const modelNodes = doc.blocks.length + 1;
612	  return { ok: previewNodes === modelNodes, modelNodes, previewNodes };
613	}
614	
615	/* ---------------- 渲染：结构体检 / 状态栏 ---------------- */
616	
617	function renderChecker() {
618	  const host = document.getElementById("checker");
619	  host.textContent = "";
620	  const issues = validate(doc);
621	  const audit = auditConsistency();
622	
623	  if (issues.length === 0 && audit.ok) {
624	    const ok = document.createElement("div");
625	    ok.className = "checker-ok";
626	    ok.textContent = "✓ 结构有效：唯一 H1、层级连续、无空标题；编辑与预览一致。";
627	    host.appendChild(ok);
628	  } else {
629	    issues.forEach((iss) => {
630	      const box = document.createElement("div");
631	      box.className = "checker-issue";
632	      box.textContent = "⚠ " + iss.msg + (iss.blocking ? "（此类状态会被操作守卫直接拒绝）" : "");
633	      host.appendChild(box);
634	    });
635	    if (!audit.ok) {
636	      const box = document.createElement("div");
637	      box.className = "checker-issue";
638	      box.textContent = `⚠ 预览节点数（${audit.previewNodes}）与模型（${audit.modelNodes}）不一致！`;
639	      host.appendChild(box);
640	    }
641	  }
642	
643	  const auditBox = document.createElement("div");
644	  auditBox.className = "checker-audit";
645	
646	  const line1 = document.createElement("span");
647	  line1.textContent = "一致性自检（每次编辑后自动运行）";
648	  const line2 = document.createElement("span");
649	  line2.className = "mono";
650	  line2.innerHTML = `模型 ${audit.modelNodes} 节点 ↔ 预览 ${audit.previewNodes} 节点 `
651	    + (audit.ok ? `<span class="pass">一致 ✓</span>` : `<span class="fail">不一致 ✗</span>`);
652	  const path = ["H1", ...doc.blocks.filter(isHeading).map((b) => "H" + TYPES[b.type].level)].join(" → ");
653	  const line3 = document.createElement("span");
654	  line3.className = "mono";
655	  line3.textContent = "层级路径：" + path;
656	
657	  auditBox.appendChild(line1);
658	  auditBox.appendChild(line2);
659	  auditBox.appendChild(line3);
660	  host.appendChild(auditBox);
661	}
662	
663	function renderStatus() {
664	  const headings = doc.blocks.filter(isHeading).length;
665	  const chars = doc.blocks.reduce((n, b) => n + b.text.length, 0) + doc.title.length;
666	  document.getElementById("status-msg").textContent = lastMsg;
667	  document.getElementById("status-stats").textContent =
668	    `块 ${doc.blocks.length} · 标题 ${headings} · 字数 ${chars}`;
669	  const badge = document.getElementById("sync-badge");
670	  badge.innerHTML = `<span class="dot"></span>已同步 ${new Date().toTimeString().slice(0, 8)}`;
671	  document.getElementById("btn-undo").disabled = !undoStack.length;
672	  document.getElementById("btn-redo").disabled = !redoStack.length;
673	}
674	
675	function renderDerived() {
676	  renderOutline();
677	  renderPreview();
678	  renderChecker();
679	  renderStatus();
680	}
681	
682	function renderAll() {
683	  renderEditor();
684	  renderDerived();
685	}
686	
687	function afterChange(msg, focusId) {
688	  if (focusId) activeId = focusId;
689	  if (msg) lastMsg = msg;
690	  renderAll();
691	  saveDoc();
692	}
693	
694	/* ---------------- 导出 Markdown ---------------- */
695	
696	function toMarkdown(d) {
697	  const lines = [];
698	  lines.push("# " + (d.title.trim() || "无标题"));
699	  let n = 0;
700	  d.blocks.forEach((b) => {
701	    const t = b.text.trim() || "（空）";
702	    if (b.type === "num") n++; else n = 0;
703	    switch (b.type) {
704	      case "h2": lines.push("", "## " + t); break;
705	      case "h3": lines.push("", "### " + t); break;
706	      case "p": lines.push("", t); break;
707	      case "bullet": lines.push("- " + t); break;
708	      case "num": lines.push(n + ". " + t); break;
709	      case "quote": lines.push("", "> " + t); break;
710	      case "callout": lines.push("", "> **提示** " + t); break;
711	    }
712	  });
713	  return lines.join("\n").replace(/\n{3,}/g, "\n\n").trim() + "\n";
714	}
715	
716	async function copyMarkdown() {
717	  const md = toMarkdown(doc);
718	  try {
719	    await navigator.clipboard.writeText(md);
720	    toast("Markdown 已复制到剪贴板", "ok");
721	  } catch (e) {
722	    try {
723	      const ta = document.createElement("textarea");
724	      ta.value = md;
725	      document.body.appendChild(ta);
726	      ta.select();
727	      const ok = document.execCommand("copy");
728	      ta.remove();
729	      toast(ok ? "Markdown 已复制" : "复制失败，请改用「导出 .md」", ok ? "ok" : "warn");
730	    } catch (e2) {
731	      toast("复制失败，请改用「导出 .md」", "warn");
732	    }
733	  }
734	}
735	
736	function downloadMarkdown() {
737	  const blob = new Blob([toMarkdown(doc)], { type: "text/markdown;charset=utf-8" });
738	  const a = document.createElement("a");
739	  const url = URL.createObjectURL(blob);
740	  a.href = url;
741	  a.download = (doc.title.trim() || "document").replace(/[\\/:*?"<>|]/g, "_").slice(0, 40) + ".md";
742	  document.body.appendChild(a);
743	  a.click();
744	  a.remove();
745	  setTimeout(() => URL.revokeObjectURL(url), 4000);
746	  toast("已下载 " + a.download, "ok");
747	}
748	
749	function resetDoc() {
750	  if (!confirm("恢复为内置示例文档？当前内容将被覆盖（可用 Ctrl+Z 撤销）。")) return;
751	  pushUndo();
752	  doc = makeSampleDoc();
753	  activeId = null;
754	  afterChange("已恢复内置示例文档");
755	}
756	
757	/* ---------------- Toast ---------------- */
758	
759	function toast(msg, kind) {
760	  if (suppressToast) return;
761	  const el = document.getElementById("toast");
762	  el.textContent = msg;
763	  el.className = "toast" + (kind === "warn" ? " toast-warn" : kind === "ok" ? " toast-ok" : "");
764	  el.hidden = false;
765	  clearTimeout(toastTimer);
766	  toastTimer = setTimeout(() => { el.hidden = true; }, 2600);
767	}
768	
769	/* ---------------- 自检（打开 index.html#selftest 触发） ---------------- */
770	
771	function runSelfTests() {
772	  const results = [];
773	  const test = (name, fn) => {
774	    try { fn(); results.push({ name, pass: true, info: "" }); }
775	    catch (e) { results.push({ name, pass: false, info: e.message }); }
776	  };
777	  const assert = (cond, msg) => { if (!cond) throw new Error(msg); };
778	  const quiet = (fn) => { suppressToast = true; try { return fn(); } finally { suppressToast = false; } };
779	
780	  test("示例文档初始结构有效", () => {
781	    doc = makeSampleDoc();
782	    assert(validate(doc).length === 0, JSON.stringify(validate(doc)));
783	  });
784	
785	  test("R2 拒绝：首块 H2 直接升级为 H3（H1→H3 跳级）", () => {
786	    doc = makeSampleDoc();
787	    const id = doc.blocks[0].id;
788	    const blocked = quiet(() => !setType(id, "h3"));
789	    assert(blocked, "跳级未被拦截");
790	    assert(doc.blocks[0].type === "h2", "被拒绝的操作修改了模型");
791	  });
792	
793	  test("R2 拒绝：删除中间 H2 导致后续 H3 悬空", () => {
794	    doc = { title: "T", blocks: [
795	      { id: "a", type: "h2", text: "A" },
796	      { id: "b", type: "h3", text: "B" },
797	      { id: "c", type: "p", text: "c" },
798	    ] };
799	    const blocked = quiet(() => !removeBlock("a"));
800	    assert(blocked && doc.blocks.length === 3, "破坏性删除未被拦截");
801	  });
802	
803	  test("R2 拒绝：H3 上移越过同级 H2", () => {
804	    doc = { title: "T", blocks: [
805	      { id: "a", type: "h2", text: "A" },
806	      { id: "b", type: "h3", text: "B" },
807	      { id: "c", type: "p", text: "c" },
808	    ] };
809	    const blocked = quiet(() => !moveBlock("b", -1));
810	    assert(blocked, "非法移动未被拦截");
811	    const allowed = quiet(() => moveBlock("b", +1));
812	    assert(allowed && validate(doc).every((x) => !x.blocking), "合法移动被误拦");
813	  });
814	
815	  test("60 步随机守卫操作后结构仍有效", () => {
816	    doc = makeSampleDoc();
817	    const pool = ["h2", "h3", "p", "bullet", "num", "quote", "callout"];
818	    quiet(() => {
819	      for (let k = 0; k < 60; k++) {
820	        if (doc.blocks.length === 0) { insertAfter(null, "p"); continue; }
821	        const b = doc.blocks[Math.floor(Math.random() * doc.blocks.length)];
822	        switch (k % 4) {
823	          case 0: setType(b.id, pool[k % pool.length]); break;
824	          case 1: moveBlock(b.id, k % 2 ? 1 : -1); break;
825	          case 2: insertAfter(b.id, "p"); break;
826	          case 3: removeBlock(b.id); break;
827	        }
828	      }
829	    });
830	    const bad = validate(doc).filter((x) => x.blocking);
831	    assert(bad.length === 0, "出现层级破坏：" + (bad[0] && bad[0].msg));
832	  });
833	
834	  test("编辑与预览一致（随机操作后节点数相等）", () => {
835	    renderAll();
836	    const a = auditConsistency();
837	    assert(a.ok, `模型 ${a.modelNodes} 节点 ≠ 预览 ${a.previewNodes} 节点`);
838	  });
839	
840	  test("Markdown 导出与模型一致", () => {
841	    doc = makeSampleDoc();
842	    renderAll();
843	    const md = toMarkdown(doc);
844	    assert(md.startsWith("# " + doc.title), "标题行不符");
845	    assert(md.includes("## 背景与目标"), "缺 H2 行");
846	    assert(md.includes("### 场景一：跨城市头脑风暴"), "缺 H3 行");
847	    assert(md.includes("1. M1"), "编号列表不符");
848	    assert(md.includes("- 目标："), "无序列表不符");
849	    assert(md.includes("> **提示** "), "提示框不符");
850	  });
851	
852	  renderAll();
853	  lastMsg = `自检完成：${results.filter((r) => r.pass).length}/${results.length} 通过`;
854	  console.table(results);
855	  renderSelfTestPanel(results);
856	  renderStatus();
857	  return results;
858	}
859	
860	function renderSelfTestPanel(results) {
861	  const host = document.getElementById("checker");
862	  const box = document.createElement("div");
863	  box.className = "checker-audit";
864	  const head = document.createElement("span");
865	  const passed = results.filter((r) => r.pass).length;
866	  head.innerHTML = `内置自检：<span class="${passed === results.length ? "pass" : "fail"}">`
867	    + `${passed}/${results.length} 通过</span>`;
868	  box.appendChild(head);
869	  results.forEach((r) => {
870	    const line = document.createElement("span");
871	    line.className = "mono";
872	    line.textContent = `${r.pass ? "✓" : "✗"} ${r.name}` + (r.pass ? "" : " —— " + r.info);
873	    box.appendChild(line);
874	  });
875	  host.appendChild(box);
876	}
877	
878	/* ---------------- 启动 ---------------- */
879	
880	function wireHeader() {
881	  document.getElementById("btn-undo").addEventListener("click", undo);
882	  document.getElementById("btn-redo").addEventListener("click", redo);
883	  document.getElementById("btn-copy-md").addEventListener("click", copyMarkdown);
884	  document.getElementById("btn-export-md").addEventListener("click", downloadMarkdown);
885	  document.getElementById("btn-reset").addEventListener("click", resetDoc);
886	
887	  document.addEventListener("keydown", (e) => {
888	    const mod = e.ctrlKey || e.metaKey;
889	    if (!mod) return;
890	    const k = e.key.toLowerCase();
891	    if (k === "z" && !e.shiftKey) { e.preventDefault(); undo(); }
892	    else if (k === "y" || (k === "z" && e.shiftKey)) { e.preventDefault(); redo(); }
893	  });
894	}
895	
896	function init() {
897	  const stored = loadDoc();
898	  doc = stored || makeSampleDoc();
899	  lastMsg = stored ? "已恢复上次编辑内容" : "就绪 · 内置示例文档已随首屏就绪";
900	  wireHeader();
901	  renderAll();
902	  if (location.hash === "#selftest" || location.search.indexOf("selftest") >= 0) {
903	    runSelfTests();
904	  }
905	}
906	
907	window.__structed = { runSelfTests, validate, toMarkdown, attempt, auditConsistency };
908	init();
